const MYSORE_INFO={id:"mysore-coinage",title:"Mysore Coinage & Tipu Sultan's Monetary System",era:"1761 – 1868 CE (Haidar Ali, Tipu Sultan, & Wodeyar Dynasty)",keyInnovator:"Tipu Sultan (Tiger of Mysore, r. 1782–1799 CE)",primaryMints:"Patan (Srirangapatna), Nagar (Bednur), Bangalore, Calicut (Feroke), Dharwar",calendarSystem:"Mauludi Solar Calendar (Epoch: 571 CE - Birth of Prophet)",famousMotif:"Striding Elephant Motif & Solar/Lunar Crescents",quickStats:[{label:"Key Innovator",value:"Tipu Sultan",icon:"🐅"},{label:"Calendar Reform",value:"Mauludi Solar Era",icon:"☀️"},{label:"Iconic Symbol",value:"Elephant Motif",icon:"🐘"},{label:"Imperial Mint",value:"Patan (Seringapatam)",icon:"🏛️"},{label:"Celestial Naming",value:"Planets & Scholars",icon:"🌌"},{label:"Primary Metals",value:"Gold, Silver, Copper",icon:"🪙"}]},COIN_DENOMINATIONS=[{id:"ahmadi-mohur",name:"Gold Ahmadi (Double Mohur)",period:"Tipu Sultan Era (1782–1799 CE)",metal:"Gold (13.7 grams)",namedAfter:"Ahmad (Title of Prophet Muhammad)",obverseText:"Din Ahmad Dar Jahan Roshan Z Fath Haidar Ast (The Religion of Ahmad is Illuminated in the World by the Victory of Haidar)",reverseText:"Huwa al-Sultan al-Wahid al-Adil - Zarb Patan Mah Bahari Year 1218 Mauludi",significance:"Highest denomination gold coin minted by Tipu Sultan at Srirangapatna.",motif:"Persian Calligraphy & Mint Date Marks"},{id:"zohra-rupee",name:"Silver Zohra (Rupee)",period:"Tipu Sultan Era (1782–1799 CE)",metal:"Silver (11.4 grams)",namedAfter:"Zohra (Planet Venus)",obverseText:"Muhammad Huwa al-Sultan al-Wahid al-Adil",reverseText:"Zarb Patan - Mauludi Year 1216",significance:"Standard silver circulation coin of the Mysore Kingdom named after Venus.",motif:"Solar Ray Burst & Crescent Moon"},{id:"bahram-copper-paisa",name:"Copper Bahram (Paisa)",period:"Tipu Sultan Era (1782–1799 CE)",metal:"Copper (11.3 grams)",namedAfter:"Bahram (Planet Mars)",obverseText:"Caparisoned Elephant striding right with raised trunk and banner",reverseText:"Zarb Nagar - Mauludi Year 1222",significance:"Most iconic copper coin bearing the famous Mysore elephant emblem.",motif:"Striding Elephant & Banner"},{id:"kanthirava-fanam",name:"Gold Kanthirava Fanam",period:"Wodeyar Dynasty (Kanthirava Narasaraja Wodeyar / Mummadi Krishnaraja Wodeyar)",metal:"Gold (0.34 grams)",namedAfter:"Kanthirava (Lion Avatar of Vishnu)",obverseText:"Narasimha avatar seated on throne with conch and discus",reverseText:"Kannada legend 'Sri Kanthirava'",significance:"Tiny gold coin used for regional trade throughout South India.",motif:"Narasimha Avatar & Kannada Script"}],MAULUDI_CALENDAR_INFO={epoch:571,explanation:"In Mauludi Year 1216 (1788 CE), Tipu Sultan changed the reckoning system from the lunar Hijri calendar to the solar Mauludi Era (starting from 571 CE). He also used the Abjad numeral system reversed (Zabt system).",conversionFormula:"Gregorian Year ≈ Mauludi Year + 571 - 1 (or 571 offset)"},MINTS_LIST=[{name:"Patan (Srirangapatna)",code:"Patan",description:"Capital mint located inside Seringapatam island fort; produced gold Ahmadis, silver Zohras, and copper Bahrams."},{name:"Nagar (Bednur)",code:"Nagar",description:"Fortified mint in Western Ghats, specialized in copper paisas with large elephant motifs."},{name:"Bangalore",code:"Bangalur",description:"Strategic fortress mint issuing silver double rupees and copper coinage."},{name:"Calicut (Feroke)",code:"Farrukhi",description:"Coastal Malabar mint established by Tipu Sultan to facilitate maritime spice trade."}],TIMELINE_EVENTS=[{year:"1761 CE",title:"Rise of Haidar Ali",description:"Haidar Ali assumes de facto ruler status of Mysore, retaining Pagoda gold coins with Shiva-Parvati motifs."},{year:"1782 CE",title:"Accession of Tipu Sultan",description:"Tipu Sultan ascends throne, introducing new minting techniques and Islamic/celestial coin naming systems."},{year:"1788 CE (Mauludi 1216)",title:"Mauludi Calendar Reform",description:"Tipu replaces Hijri calendar on coins with the solar Mauludi Era and reversed Abjad numeral script."},{year:"1799 CE",title:"Fall of Seringapatam",description:"Death of Tipu Sultan in 4th Anglo-Mysore War; British restore Wodeyar dynasty under Krishna Raja Wodeyar III."}],REFERENCES=[{text:"Henderson, J. R. (1921). The Coins of Haidar Ali and Tipu Sultan. Government Press, Madras.",link:"#"},{text:"Hawkes, H. P. (1857). A Brief Sketch of the Gold and Silver Coins of Mysore. Bangalore.",link:"#"},{text:"Khurana, G. (2018). Numismatic Heritage of Mysore & Malabar Mints. Journal of Indian Numismatics.",link:"#"}];"undefined"!=typeof module&&module.exports&&(module.exports={MYSORE_INFO:MYSORE_INFO,COIN_DENOMINATIONS:COIN_DENOMINATIONS,MAULUDI_CALENDAR_INFO:MAULUDI_CALENDAR_INFO,MINTS_LIST:MINTS_LIST,TIMELINE_EVENTS:TIMELINE_EVENTS,REFERENCES:REFERENCES});